cd /tmp/probe && python3 -c "
import subprocess
escaped=[]; passed=[]; failed=[]
for b in range(0x20,0x7f):
    c=chr(b)
    if c in '\"\\\\': continue
    src='\"'+c+'\";'
    p=subprocess.run(['/workspace/executable'],input=src.encode(),capture_output=True)
    if p.returncode!=0: failed.append(c)
    elif p.stdout==('\\\\'+c+'\n').encode(): escaped.append(c)
    elif p.stdout==(c+'\n').encode(): passed.append(c)
    else: print('ODD',repr(c),p.stdout)
print('ESCAPED:',repr(''.join(escaped)))
print('PASSED :',repr(''.join(passed)))
print('FAILED :',repr(''.join(failed)))
"
